// Card data is generated by ../../export_cards.js from cards.db — don't edit
// cards.json by hand; rerun the export.
import cards from "../data/cards.json";
import type { Pack } from "./ship";

export interface Card {
  id: number;
  slug: string;
  title: string;
  player: string;
  number: string;
  year: string;
  set: string;
  sport: string;
  team: string;
  condition: string;
  price_cents: number;
  front: string;
  front_sm: string;
  back: string | null;
  back_sm: string | null;
  pack: Pack;            // sleeve | toploader | slab | pack, set by export_cards.js
}

// Cards exported before packaging existed default to a penny sleeve.
export const allCards = (cards as Card[]).map((c) => ({ ...c, pack: c.pack ?? "sleeve" }));

export const price = (cents: number) => `$${(cents / 100).toFixed(2)}`;

export const heading = (c: Card) => `${c.year} ${c.set} ${c.player} #${c.number}`;

export const byId = new Map(allCards.map((c) => [c.id, c]));
